/*
 * SHA-256 AVX2 implementation based on Intel's sha256-avx2 (public domain / BSD).
 * Processes 2 blocks (128 bytes) per iteration using AVX2.
 * Adapted from Intel's sha256_avx2_rorx implementation (intel-ipsec-mb / cryptogams).
 *
 * For simplicity and correctness we implement a clean scalar-but-unrolled version first
 * compiled with -O3 -march=native, then compare. If not fast enough, use AVX2.
 */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <immintrin.h>

static const uint32_t K[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

static inline uint32_t rotr(uint32_t x, int n) { return (x >> n) | (x << (32 - n)); }
static inline uint32_t bswap32(uint32_t x) { return __builtin_bswap32(x); }

static void sha256_transform(uint32_t state[8], const uint8_t block[64]) {
    uint32_t w[64];
    const uint32_t *m = (const uint32_t *)block;
    for (int i = 0; i < 16; i++) w[i] = bswap32(m[i]);
    for (int i = 16; i < 64; i++) {
        uint32_t s0 = rotr(w[i-15], 7) ^ rotr(w[i-15], 18) ^ (w[i-15] >> 3);
        uint32_t s1 = rotr(w[i-2], 17) ^ rotr(w[i-2], 19) ^ (w[i-2] >> 10);
        w[i] = w[i-16] + s0 + w[i-7] + s1;
    }
    uint32_t a=state[0], b=state[1], c=state[2], d=state[3];
    uint32_t e=state[4], f=state[5], g=state[6], h=state[7];
    for (int i = 0; i < 64; i++) {
        uint32_t S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
        uint32_t ch = (e & f) ^ (~e & g);
        uint32_t t1 = h + S1 + ch + K[i] + w[i];
        uint32_t S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
        uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        uint32_t t2 = S0 + maj;
        h = g; g = f; f = e; e = d + t1;
        d = c; c = b; b = a; a = t1 + t2;
    }
    state[0]+=a; state[1]+=b; state[2]+=c; state[3]+=d;
    state[4]+=e; state[5]+=f; state[6]+=g; state[7]+=h;
}

void sha256(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t state[8] = {
        0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
        0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19
    };
    size_t nblocks = len / 64;
    for (size_t i = 0; i < nblocks; i++) sha256_transform(state, data + i*64);
    // padding
    uint8_t block[128];
    size_t rem = len % 64;
    memcpy(block, data + nblocks*64, rem);
    block[rem] = 0x80;
    memset(block + rem + 1, 0, 128 - rem - 1);
    size_t padblocks = (rem + 1 + 8 <= 64) ? 1 : 2;
    uint64_t bits = (uint64_t)len * 8;
    // big-endian length at end of last block
    uint8_t *end = block + padblocks*64 - 8;
    for (int i = 7; i >= 0; i--) { end[i] = bits & 0xff; bits >>= 8; }
    for (size_t i = 0; i < padblocks; i++) sha256_transform(state, block + i*64);
    for (int i = 0; i < 8; i++) {
        out[i*4]   = state[i] >> 24;
        out[i*4+1] = state[i] >> 16;
        out[i*4+2] = state[i] >> 8;
        out[i*4+3] = state[i];
    }
}

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    size_t n = 20000*1024;
    uint8_t *data = malloc(n);
    memset(data, 0xab, n);
    uint8_t md[32];
    sha256(data, n, md);
    double t0 = now();
    int reps = 3;
    for (int i = 0; i < reps; i++) sha256(data, n, md);
    double t1 = now();
    printf("scalar: %.4f s (%.1f MB/s) ", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));
    for (int i = 0; i < 8; i++) printf("%02x", md[i]);
    printf("...\n");
    free(data);
    return 0;
}
EOF
