static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

typedef struct { const unsigned char *data; size_t len; unsigned char md[32]; } job;

void *worker(void *arg) {
    job *j = arg;
    SHA256(j->data, j->len, j->md);
    return NULL;
}

int main() {
    size_t n = 20000*1024;
    unsigned char *data = malloc(n);
    memset(data, 0xab, n);
    int threads = 6;
    job jobs[16];
    pthread_t th[16];
    size_t chunk = n / threads;
    // warmup
    for (int t = 0; t < threads; t++) {
        jobs[t].data = data + t*chunk;
        jobs[t].len = chunk;
    }
    for (int t = 0; t < threads; t++) pthread_create(&th[t], NULL, worker, &jobs[t]);
    for (int t = 0; t < threads; t++) pthread_join(th[t], NULL);

    double t0 = now();
    int reps = 3;
    for (int r = 0; r < reps; r++) {
        for (int t = 0; t < threads; t++) pthread_create(&th[t], NULL, worker, &jobs[t]);
        for (int t = 0; t < threads; t++) pthread_join(th[t], NULL);
    }
    double t1 = now();
    printf("%d threads: %.4f s (%.1f MB/s wall)\n", threads, (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    // single
    unsigned char md[32];
    t0 = now();
    for (int r = 0; r < reps; r++) SHA256(data, n, md);
