import os, time, hashlib, multiprocessing as mp

def worker(data, start, end, q):
    q.put(hashlib.sha256(data[start:end]).digest())

def bench_threads_via_process():
    data = os.urandom(20_000*1024)
    # single
    t0 = time.perf_counter()
    for _ in range(2):
        hashlib.sha256(data).digest()
    print("single", (time.perf_counter()-t0)/2)

    for nproc in (2, 4, 6):
        chunk = len(data)//nproc
        t0 = time.perf_counter()
        reps = 2
        for _ in range(reps):
            q = mp.Queue()
            ps = []
            for i in range(nproc):
                s = i*chunk
                e = (i+1)*chunk if i < nproc-1 else len(data)
                p = mp.Process(target=worker, args=(data, s, e, q))
                p.start(); ps.append(p)
            for p in ps: p.join()
            res = [q.get() for _ in range(nproc)]
        print(nproc, "procs", (time.perf_counter()-t0)/reps)

if __name__ == "__main__":
    bench_threads_via_process()
EOF"}

