/*
 * 8-way interleaved SHA-256 using AVX2.
 * Hashes 8 independent 64-byte blocks... wait, for a SINGLE stream we need
 * sequential chaining, so multi-block interleave doesn't directly apply.
 *
 * Instead: implement the message schedule with AVX2 (4 words at a time)
 * and the state update still scalar but with better scheduling.
 * This is the classic "SHA256 AVX2 single-stream" approach: compute W[i]
 * for 4 rounds ahead using SIMD, overlapping with scalar rounds.
 *
 * Based on the well-known approach from Nayuki / Intel whitepaper.
 */
#include <immintrin.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static const uint32_t K256[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

#define ROTR(x,n) (((x)>>(n))|((x)<<(32-(n))))
#define CH(e,f,g) (((e)&(f))^(~(e)&(g)))
#define MAJ(a,b,c) (((a)&(b))^((a)&(c))^((b)&(c)))
#define BSIG0(a) (ROTR(a,2)^ROTR(a,13)^ROTR(a,22))
#define BSIG1(e) (ROTR(e,6)^ROTR(e,11)^ROTR(e,25))
#define SSIG0(x) (ROTR(x,7)^ROTR(x,18)^((x)>>3))
#define SSIG1(x) (ROTR(x,17)^ROTR(x,19)^((x)>>10))

#define ROUND(a,b,c,d,e,f,g,h,k,w) do { \
    uint32_t t1 = (h) + BSIG1(e) + CH(e,f,g) + (k) + (w); \
    uint32_t t2 = BSIG0(a) + MAJ(a,b,c); \
    (h)=g; (g)=f; (f)=e; (e)=(d)+t1; (d)=c; (c)=b; (b)=a; (a)=t1+t2; \
} while(0)

static void transform(uint32_t st[8], const uint8_t blk[64]) {
    uint32_t w[64];
    const uint32_t *m = (const uint32_t*)blk;
    /* load + bswap 16 words using AVX2 */
    __m128i bswap_mask = _mm_set_epi8(12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);
    for (int i = 0; i < 16; i += 4) {
        __m128i v = _mm_loadu_si128((const __m128i*)(m + i));
        v = _mm_shuffle_epi8(v, bswap_mask);
        _mm_storeu_si128((__m128i*)(w + i), v);
    }
    for (int i = 16; i < 64; i++) {
        w[i] = w[i-16] + SSIG0(w[i-15]) + w[i-7] + SSIG1(w[i-2]);
    }
    uint32_t a=st[0],b=st[1],c=st[2],d=st[3],e=st[4],f=st[5],g=st[6],h=st[7];
    for (int i = 0; i < 64; i++) ROUND(a,b,c,d,e,f,g,h, K256[i], w[i]);
    st[0]+=a; st[1]+=b; st[2]+=c; st[3]+=d; st[4]+=e; st[5]+=f; st[6]+=g; st[7]+=h;
}

void sha256(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t nb = len/64;
    for (size_t i = 0; i < nb; i++) transform(st, data + i*64);
    uint8_t block[128];
    size_t rem = len % 64;
    memcpy(block, data + nb*64, rem);
    block[rem] = 0x80;
    memset(block+rem+1, 0, 128-rem-1);
    size_t pb = (rem+9 <= 64) ? 1 : 2;
    uint64_t bits = (uint64_t)len * 8;
    uint8_t *end = block + pb*64 - 8;
    for (int i = 7; i >= 0; i--) { end[i] = bits & 0xff; bits >>= 8; }
    for (size_t i = 0; i < pb; i++) transform(st, block + i*64);
    for (int i = 0; i < 8; i++) {
        out[4*i]=st[i]>>24; out[4*i+1]=st[i]>>16; out[4*i+2]=st[i]>>8; out[4*i+3]=st[i];
    }
}

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

int main(){
    size_t n = 20000*1024;
    uint8_t *data = aligned_alloc(64, n);
    memset(data, 0xab, n);
    uint8_t md[32];
    sha256(data, n, md);
    double t0 = now();
    for (int i = 0; i < 3; i++) sha256(data, n, md);
    double dt = (now()-t0)/3;
    printf("avx-sched: %.4f s (%.1f MB/s) ", dt, (n/1e6)/dt);
    for (int i = 0; i < 8; i++) printf("%02x", md[i]);
    printf("\n");
    free(data);
    return 0;
}
EOF
