    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

#define ROTR(x,n) _mm256_or_si256(_mm256_srli_epi32(x,n), _mm256_slli_epi32(x,32-(n)))

static inline __m256i s0(__m256i x){
    return _mm256_xor_si256(_mm256_xor_si256(ROTR(x,7), ROTR(x,18)), _mm256_srli_epi32(x,3));
}
static inline __m256i s1(__m256i x){
    return _mm256_xor_si256(_mm256_xor_si256(ROTR(x,17), ROTR(x,19)), _mm256_srli_epi32(x,10));
}
static inline __m256i S0(__m256i x){
    return _mm256_xor_si256(_mm256_xor_si256(ROTR(x,2), ROTR(x,13)), ROTR(x,22));
}
static inline __m256i S1(__m256i x){
    return _mm256_xor_si256(_mm256_xor_si256(ROTR(x,6), ROTR(x,11)), ROTR(x,25));
}
static inline __m256i ch(__m256i e, __m256i f, __m256i g){
    return _mm256_xor_si256(_mm256_and_si256(e,f), _mm256_andnot_si256(e,g));
}
static inline __m256i maj(__m256i a, __m256i b, __m256i c){
    return _mm256_xor_si256(_mm256_xor_si256(_mm256_and_si256(a,b), _mm256_and_si256(a,c)), _mm256_and_si256(b,c));
}

/* 8 lanes, each block is 64 bytes. blocks[lane] points to 64-byte block. */
static void transform8(__m256i st[8], const uint8_t *blocks[8]) {
    __m256i w[64];
    const __m128i shuf = _mm_set_epi8(12,13,14,15,8,9,10,11,4,5,6,7,0,1,2,3);
    for (int i = 0; i < 16; i += 4) {
        /* gather 4 words x 8 lanes -> tricky. Do scalar load per lane then transpose via set. */
    }
    uint32_t tmp[8];
    for (int i = 0; i < 16; i++) {
        for (int lane = 0; lane < 8; lane++) {
            uint32_t v;
            memcpy(&v, blocks[lane] + i*4, 4);
            tmp[lane] = __builtin_bswap32(v);
        }
        w[i] = _mm256_loadu_si256((const __m256i*)tmp);
    }
    for (int i = 16; i < 64; i++) {
        w[i] = _mm256_add_epi32(_mm256_add_epi32(w[i-16], s0(w[i-15])),
                                _mm256_add_epi32(w[i-7], s1(w[i-2])));
    }
    __m256i a=st[0],b=st[1],c=st[2],d=st[3],e=st[4],f=st[5],g=st[6],h=st[7];
    for (int i = 0; i < 64; i++) {
        __m256i t1 = _mm256_add_epi32(h, _mm256_add_epi32(S1(e), _mm256_add_epi32(ch(e,f,g),
                        _mm256_add_epi32(_mm256_set1_epi32(K[i]), w[i]))));
        __m256i t2 = _mm256_add_epi32(S0(a), maj(a,b,c));
        h=g; g=f; f=e; e=_mm256_add_epi32(d,t1); d=c; c=b; b=a; a=_mm256_add_epi32(t1,t2);
    }
    st[0]=_mm256_add_epi32(st[0],a); st[1]=_mm256_add_epi32(st[1],b);
    st[2]=_mm256_add_epi32(st[2],c); st[3]=_mm256_add_epi32(st[3],d);
    st[4]=_mm256_add_epi32(st[4],e); st[5]=_mm256_add_epi32(st[5],f);
    st[6]=_mm256_add_epi32(st[6],g); st[7]=_mm256_add_epi32(st[7],h);
}

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

int main(){
    size_t n = 20000*1024;
    uint8_t *data = aligned_alloc(64, n);
    memset(data, 0xab, n);
    size_t nblocks = n/64;
    size_t groups = nblocks/8; /* 8 blocks per group */
    __m256i st[8];
    uint32_t init[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    for (int i = 0; i < 8; i++) st[i] = _mm256_set1_epi32(init[i]);

    const uint8_t *bp[8];
    /* warmup */
    for (size_t g = 0; g < groups; g++) {
        for (int lane = 0; lane < 8; lane++) bp[lane] = data + (g*8 + lane)*64;
        transform8(st, bp);
    }
    for (int i = 0; i < 8; i++) st[i] = _mm256_set1_epi32(init[i]);
    double t0 = now();
    for (size_t g = 0; g < groups; g++) {
        for (int lane = 0; lane < 8; lane++) bp[lane] = data + (g*8 + lane)*64;
        transform8(st, bp);
    }
    double dt = now()-t0;
    printf("8-way avx2: %.4f s (%.1f MB/s)\n", dt, (n/1e6)/dt);

    /* also 4-way using xmm? skip */
    /* contiguous-lane variant: each lane processes a strided region to be cache friendly?
       try lanes reading consecutive 64B but from 8 separate big chunks */
    size_t chunk = (n/8) & ~63;
    for (int i = 0; i < 8; i++) st[i] = _mm256_set1_epi32(init[i]);
    size_t blocks_per_lane = chunk/64;
    t0 = now();
    for (size_t b = 0; b < blocks_per_lane; b++) {
        for (int lane = 0; lane < 8; lane++) bp[lane] = data + lane*chunk + b*64;
        transform8(st, bp);
    }
    dt = now()-t0;
    printf("8-way chunked: %.4f s (%.1f MB/s)\n", dt, (8.0*chunk/1e6)/dt);
    return 0;
}
