#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <unistd.h>
#include <time.h>
#include <openssl/sha.h>

/* Original function at vmaddr 0x249a40.
 * RIP-relative refs (addr is the address of the displacement field? we compute target from disassembly):
 *   249aaa: vmovdqa 0x1856ee(%rip), %ymm8   ; disp at 249ab1? need exact insn length
 *   249ab2: vmovdqa 0x185706(%rip), %ymm9
 *   249ac0: vmovdqa 0x1856b8(%rip), %ymm7
 * We'll compute targets from the next-instruction address once we know insn lengths.
 */

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

int main(){
    FILE *f = fopen("avx2_blob.bin","rb");
    fseek(f,0,SEEK_END); long sz = ftell(f); fseek(f,0,SEEK_SET);
    uint8_t *blob = malloc(sz);
    fread(blob,1,sz,f); fclose(f);

    /* Disassembly says:
       249aaa vmovdqa 0x1856ee(%rip), %ymm8
       249ab2 vmovdqa 0x185706(%rip), %ymm9
       so first insn is 8 bytes (249aaa..249ab1), disp is last 4 bytes -> disp field at 249aae.
       249ab2 is 8 bytes (to 249ab9), disp at 249ab6.
       249ac0 is 8 bytes (to 249ac7), disp at 249ac4.
    */
    uint32_t orig_base = 0x249a40;
    struct { uint32_t disp_off; uint32_t next_off; } refs[3];
    /* offsets within blob */
    refs[0].disp_off = 0x249aae - orig_base; refs[0].next_off = 0x249ab2 - orig_base;
    refs[1].disp_off = 0x249ab6 - orig_base; refs[1].next_off = 0x249aba - orig_base;
    refs[2].disp_off = 0x249ac4 - orig_base; refs[2].next_off = 0x249ac8 - orig_base;

    /* compute absolute targets in original image */
    uint64_t targets[3];
    for (int i = 0; i < 3; i++) {
        int32_t disp;
        memcpy(&disp, blob + refs[i].disp_off, 4);
        uint64_t next = orig_base + refs[i].next_off;
        targets[i] = next + disp;
        printf("ref%d disp_off=%x disp=%d target=%llx\n", i, refs[i].disp_off, disp, (unsigned long long)targets[i]);
    }

    /* read original K512 table (32 bytes each, 3 of them) from libcrypto */
    FILE *lib = fopen("/usr/local/lib/libcrypto.3.dylib","rb");
    uint8_t tables[3][32];
    for (int i = 0; i < 3; i++) {
        fseek(lib, targets[i], SEEK_SET);
        fread(tables[i], 1, 32, lib);
        printf("table%d: ", i);
        for (int j = 0; j < 32; j++) printf("%02x", tables[i][j]);
        printf("\n");
    }
    fclose(lib);

    /* allocate executable page: code + tables */
    size_t pagesz = 16384;
    size_t total = (sz + 256 + pagesz - 1) & ~(pagesz-1);
    uint8_t *mem = mmap(NULL, total, PROT_READ|PROT_WRITE|PROT_EXEC, MAP_PRIVATE|MAP_ANON, -1, 0);
    if (mem == MAP_FAILED) { perror("mmap"); return 1; }
    memcpy(mem, blob, sz);
    /* place tables at end */
    uint8_t *tdest[3];
    for (int i = 0; i < 3; i++) {
        tdest[i] = mem + sz + 64 + i*64; /* align 64 */
        tdest[i] = (uint8_t*)(((uintptr_t)tdest[i] + 31) & ~31);
        memcpy(tdest[i], tables[i], 32);
    }
    /* patch displacements */
    for (int i = 0; i < 3; i++) {
        uint64_t next = (uint64_t)(mem + refs[i].next_off);
        int64_t ndisp = (int64_t)(tdest[i]) - (int64_t)next;
        if (ndisp > 0x7fffffff || ndisp < -0x80000000) { printf("disp out of range\n"); return 1; }
        int32_t d = (int32_t)ndisp;
        memcpy(mem + refs[i].disp_off, &d, 4);
        printf("patched ref%d new disp=%d\n", i, d);
    }

    /* signature: void sha256_block_data_order(uint32_t state[8], const uint8_t *data, size_t nblocks) */
    typedef void (*fn_t)(uint32_t *, const uint8_t *, size_t);
    fn_t fn = (fn_t)mem;

    /* test vector: "abc" */
    const char *msg = "abc";
    uint8_t buf[64];
    memset(buf, 0, 64);
    memcpy(buf, msg, 3);
    buf[3] = 0x80;
    /* length 24 bits = 0x18 at end */
    buf[63] = 24;
    uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    fn(st, buf, 1);
    uint8_t out[32];
    for (int i = 0; i < 8; i++) {
        out[4*i]=st[i]>>24; out[4*i+1]=st[i]>>16; out[4*i+2]=st[i]>>8; out[4*i+3]=st[i];
    }
    unsigned char ref[32];
    SHA256((unsigned char*)msg, 3, ref);
    printf("ours: "); for(int i=0;i<32;i++) printf("%02x", out[i]); printf("\n");
    printf("ref : "); for(int i=0;i<32;i++) printf("%02x", ref[i]); printf("\n");
    printf("match %d\n", memcmp(out, ref, 32)==0);

    /* benchmark large */
    size_t n = 20000*1024;
    uint8_t *data = aligned_alloc(64, n);
    memset(data, 0xab, n);
    uint32_t st2[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    /* warmup */
    fn(st2, data, n/64);
    for (int i = 0; i < 8; i++) st2[i] = (uint32_t[]){0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19}[i];
    double t0 = now();
    int reps = 3;
    for (int r = 0; r < reps; r++) {
        for (int i = 0; i < 8; i++) st2[i] = (uint32_t[]){0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19}[i];
        fn(st2, data, n/64);
    }
    double dt = (now()-t0)/reps;
    printf("extracted avx2: %.4f s (%.1f MB/s)\n", dt, (n/1e6)/dt);
    return 0;
}
