#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <dlfcn.h>
#include <openssl/sha.h>

int main(){
    setvbuf(stdout, NULL, _IONBF, 0);
    void *h = dlopen("/usr/local/lib/libcrypto.3.dylib", RTLD_NOW);
    void *sym = dlsym(h, "sha256_block_data_order");
    uintptr_t base = (uintptr_t)sym - 0x246740;
    uint8_t *orig = (uint8_t*)(base + 0x249a40);
    size_t sz = 0x1423;
    size_t pagesz = 16384;
    size_t total = (sz + pagesz - 1) & ~(pagesz - 1);

    /* map right after the function, within 2GB */
    uintptr_t region = (base + 0x250000) & ~(pagesz - 1);
    uint8_t *mem = NULL;
    for (int i = 0; i < 128; i++) {
        void *hint = (void*)(region + (uintptr_t)i * 65536);
        void *p = mmap(hint, total, PROT_READ|PROT_WRITE|PROT_EXEC, MAP_PRIVATE|MAP_ANON, -1, 0);
        if (p == MAP_FAILED) { printf("fail hint %p\n", hint); continue; }
        int64_t dist = (int64_t)p - (int64_t)orig;
        printf("got %p dist %lld\n", p, (long long)dist);
        if (llabs(dist) < 0x70000000LL) { mem = p; break; }
        munmap(p, total);
    }
    if (!mem) { printf("no mem\n"); return 1; }
    memcpy(mem, orig, sz);

    /* recompute disp32 for the 3 refs so they still point at original tables.
       disp field offsets within function: 0x6e, 0x76, 0x84; next insn at +4. */
    int disp_offs[3] = {0x6e, 0x76, 0x84};
    for (int i = 0; i < 3; i++) {
        int32_t old;
        memcpy(&old, orig + disp_offs[i], 4);
        uint64_t old_next = (uint64_t)(orig + disp_offs[i] + 4);
        uint64_t target = old_next + old;
        uint64_t new_next = (uint64_t)(mem + disp_offs[i] + 4);
        int64_t nd = (int64_t)target - (int64_t)new_next;
        printf("ref%d old_disp %d target %llx new_disp %lld\n", i, old, (unsigned long long)target, (long long)nd);
        int32_t d = (int32_t)nd;
        memcpy(mem + disp_offs[i], &d, 4);
    }

    typedef void (*fn_t)(uint32_t *, const uint8_t *, size_t);
    fn_t fn = (fn_t)mem;
    uint8_t buf[64]; memset(buf,0,64); memcpy(buf,"abc",3); buf[3]=0x80; buf[63]=24;
    uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    printf("calling copy\n");
    fn(st, buf, 1);
    printf("returned\n");
    uint8_t out[32];
    for (int i=0;i<8;i++){ out[4*i]=st[i]>>24; out[4*i+1]=st[i]>>16; out[4*i+2]=st[i]>>8; out[4*i+3]=st[i]; }
    unsigned char ref[32]; SHA256((unsigned char*)"abc",3,ref);
    printf("match %d\n", memcmp(out,ref,32)==0);
    return 0;
}
