static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }
static inline uint64_t rdtsc(){ uint32_t lo,hi; __asm__ volatile("rdtsc":"=a"(lo),"=d"(hi)); return ((uint64_t)hi<<32)|lo; }

typedef void (*fn_t)(uint32_t*, const uint8_t*, size_t);

void *burn(void *arg){
    volatile uint64_t x = 0;
    double t = now();
    while (now()-t < 1.5) { x += 1; }
    return NULL;
}

int main(){
    void *h = dlopen("/usr/local/lib/libcrypto.3.dylib", RTLD_NOW);
    fn_t fn = (fn_t)dlsym(h, "sha256_block_data_order");
    size_t n = 20000*1024;
    uint8_t *data = aligned_alloc(64, n);
    memset(data, 0xab, n);
    uint32_t init[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    uint32_t st[8];
    size_t nb = n/64;

    /* cold */
    memcpy(st, init, 32);
    uint64_t c0 = rdtsc(); double t0 = now();
    fn(st, data, nb);
    double dt = now()-t0; uint64_t cyc = rdtsc()-c0;
    printf("cold: %.4fs (%.0f MB/s) cycles/byte %.2f\n", dt, (n/1e6)/dt, (double)cyc/n);

    /* warm back to back */
    for (int i = 0; i < 5; i++) {
        memcpy(st, init, 32);
        c0 = rdtsc(); t0 = now();
        fn(st, data, nb);
        dt = now()-t0; cyc = rdtsc()-c0;
        printf("warm%d: %.4fs (%.0f MB/s) cyc/byte %.2f\n", i, dt, (n/1e6)/dt, (double)cyc/n);
    }

    /* with background load */
    pthread_t th[4];
    for (int i = 0; i < 4; i++) pthread_create(&th[i], NULL, burn, NULL);
    for (int i = 0; i < 3; i++) {
        memcpy(st, init, 32);
        c0 = rdtsc(); t0 = now();
        fn(st, data, nb);
        dt = now()-t0; cyc = rdtsc()-c0;
        printf("loaded%d: %.4fs (%.0f MB/s) cyc/byte %.2f\n", i, dt, (n/1e6)/dt, (double)cyc/n);
    }
    for (int i = 0; i < 4; i++) pthread_join(th[i], NULL);
    return 0;
}
