static inline __m128i s0(__m128i x){ return _mm_xor_si128(_mm_xor_si128(ROTR(x,7),ROTR(x,18)),_mm_srli_epi32(x,3)); }
static inline __m128i s1(__m128i x){ return _mm_xor_si128(_mm_xor_si128(ROTR(x,17),ROTR(x,19)),_mm_srli_epi32(x,10)); }
static inline __m128i S0(__m128i x){ return _mm_xor_si128(_mm_xor_si128(ROTR(x,2),ROTR(x,13)),ROTR(x,22)); }
static inline __m128i S1(__m128i x){ return _mm_xor_si128(_mm_xor_si128(ROTR(x,6),ROTR(x,11)),ROTR(x,25)); }
static inline __m128i ch(__m128i e,__m128i f,__m128i g){ return _mm_xor_si128(_mm_and_si128(e,f),_mm_andnot_si128(e,g)); }
static inline __m128i maj(__m128i a,__m128i b,__m128i c){ return _mm_xor_si128(_mm_xor_si128(_mm_and_si128(a,b),_mm_and_si128(a,c)),_mm_and_si128(b,c)); }

static void t4(__m128i st[8], const uint8_t *b[4]){
    __m128i w[64];
