/*
 * Single-stream SHA-256 with SSSE3 message schedule (vpshufb) and scalar
 * state rounds using rorx, fully unrolled. This mirrors the classic fast
 * approach. Goal: measure if we can beat openssl's 6.5 cyc/byte.
 */
#include <immintrin.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static const uint32_t K[64] __attribute__((aligned(64))) = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

#define ROR(x,n) ({ uint32_t r; __asm__("rorxl %2,%1,%0":"=r"(r):"r"(x),"i"(n)); r; })
#define CH(e,f,g) (((e)&(f))^((~(e))&(g)))
#define MAJ(a,b,c) (((a)&(b))^((a)&(c))^((b)&(c)))

#define RND(a,b,c,d,e,f,g,h,i) do{ \
  uint32_t s1=ROR(e,6)^ROR(e,11)^ROR(e,25); \
  uint32_t t1=h+s1+CH(e,f,g)+K[i]+w[i]; \
  uint32_t s0=ROR(a,2)^ROR(a,13)^ROR(a,22); \
  d=d+t1; h=t1+s0+MAJ(a,b,c); }while(0)

__attribute__((noinline))
static void transform(uint32_t st[8], const uint8_t *blk){
    uint32_t w[64];
    __m128i shuf = _mm_set_epi8(12,13,14,15,8,9,10,11,4,5,6,7,0,1,2,3);
    for(int i=0;i<16;i+=4){
        __m128i v=_mm_loadu_si128((const __m128i*)(blk+i*4));
        v=_mm_shuffle_epi8(v,shuf);
        _mm_storeu_si128((__m128i*)(w+i),v);
    }
    for(int i=16;i<64;i++){
        uint32_t x=w[i-15]; uint32_t s0=ROR(x,7)^ROR(x,18)^(x>>3);
        uint32_t y=w[i-2]; uint32_t s1=ROR(y,17)^ROR(y,19)^(y>>10);
        w[i]=w[i-16]+s0+w[i-7]+s1;
    }
    uint32_t a=st[0],b=st[1],c=st[2],d=st[3],e=st[4],f=st[5],g=st[6],h=st[7];
    /* rotate-in-place rounds: after each round the roles shift, but we use the
       macro which reassigns d and h only... that macro is wrong for rotation.
       Use explicit rotation by cycling variables via the standard approach. */
    #define RR(a,b,c,d,e,f,g,h,i) do{ \
        uint32_t s1=ROR(e,6)^ROR(e,11)^ROR(e,25); \
        uint32_t t1=h+s1+CH(e,f,g)+K[i]+w[i]; \
        uint32_t s0=ROR(a,2)^ROR(a,13)^ROR(a,22); \
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+s0+MAJ(b,c,d); \
    }while(0)
    /* The macro above uses a after reassignment incorrectly for MAJ. Fix: */
    #undef RR
    #define RR(A,B,C,D,E,F,G,H,i) do{ \
        uint32_t s1=ROR(E,6)^ROR(E,11)^ROR(E,25); \
        uint32_t t1=(H)+s1+CH(E,F,G)+K[i]+w[i]; \
        uint32_t s0=ROR(A,2)^ROR(A,13)^ROR(A,22); \
        uint32_t t2=s0+MAJ(A,B,C); \
        (H)=(G); (G)=(F); (F)=(E); (E)=(D)+t1; (D)=(C); (C)=(B); (B)=(A); (A)=t1+t2; \
    }while(0)
    RR(a,b,c,d,e,f,g,h,0);RR(a,b,c,d,e,f,g,h,1);RR(a,b,c,d,e,f,g,h,2);RR(a,b,c,d,e,f,g,h,3);
    RR(a,b,c,d,e,f,g,h,4);RR(a,b,c,d,e,f,g,h,5);RR(a,b,c,d,e,f,g,h,6);RR(a,b,c,d,e,f,g,h,7);
    RR(a,b,c,d,e,f,g,h,8);RR(a,b,c,d,e,f,g,h,9);RR(a,b,c,d,e,f,g,h,10);RR(a,b,c,d,e,f,g,h,11);
    RR(a,b,c,d,e,f,g,h,12);RR(a,b,c,d,e,f,g,h,13);RR(a,b,c,d,e,f,g,h,14);RR(a,b,c,d,e,f,g,h,15);
